<?php require __DIR__.'/../../bootstrap/app.php';role_any(['admin','staff']);$db=Database::get();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$a=$_POST['action']??'';
 if($a==='status'&&in_array($_POST['status']??'',['under_review','quoted','approved','rejected','in_progress','completed','cancelled'],true)){$db->prepare("UPDATE service_requests SET status=? WHERE id=?")->execute([$_POST['status'],$id]);audit('request '.$_POST['status'],'service_request',$id);notice('Request updated.');}
 if($a==='assign'&&user()['role']==='admin'){$t=(int)($_POST['technician_id']??0);$ok=$db->prepare("SELECT COUNT(*) FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? AND r.name='technical' AND u.status='active'");$ok->execute([$t]);
  if($ok->fetchColumn()){$db->prepare("UPDATE service_assignments SET status='cancelled' WHERE request_id=? AND status IN('offered','accepted')")->execute([$id]);$db->prepare("INSERT INTO service_assignments(request_id,technician_id) VALUES(?,?)")->execute([$id,$t]);$db->prepare("UPDATE service_requests SET status='assigned' WHERE id=?")->execute([$id]);audit('assign technician','service_request',$id,['technician'=>$t]);notice('Technician assigned.');}else notice('Choose an active technical user.');}
 go('admin/requests.php');}
$rows=$db->query("SELECT sr.id,sr.description,sr.address,sr.preferred_date,sr.status,sr.created_at,u.name cname,u.email,s.name sname FROM service_requests sr JOIN users u ON u.id=sr.customer_id JOIN services s ON s.id=sr.service_id ORDER BY (sr.status='submitted') DESC,sr.id DESC LIMIT 100")->fetchAll();
$asg=[];foreach($db->query("SELECT a.request_id,a.status,u.name FROM service_assignments a JOIN users u ON u.id=a.technician_id ORDER BY a.id")->fetchAll() as $x)$asg[$x['request_id']][]=$x;
$techs=$db->query("SELECT u.id,u.name FROM users u JOIN roles r ON r.id=u.role_id WHERE r.name='technical' AND u.status='active' ORDER BY u.name")->fetchAll();
$title='Service requests';require __DIR__.'/../../app/Views/header.php';?><section class="section"><div class="container"><div class="dash"><?php require __DIR__.'/../../app/Views/admin_nav.php';?><div><h1>Service requests</h1>
<?php if(!$rows):?><p>No service requests yet.</p><?php endif;?><?php foreach($rows as $r):?><div class="cardx mb-3"><b><?=e($r['sname'])?></b> · <?=e($r['cname'])?> (<?=e($r['email'])?>) · <small><?=e($r['created_at'])?></small> · <span class="badge bg-secondary"><?=e($r['status'])?></span><p class="mt-2 mb-1"><?=nl2br(e($r['description']))?></p><small>Address: <?=e($r['address'])?> · Preferred date: <?=e((string)$r['preferred_date'])?></small>
<form method="post" class="mt-2"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="action" value="status"><?php foreach(['under_review'=>'Review','quoted'=>'Quoted','approved'=>'Approve','rejected'=>'Reject','in_progress'=>'In progress','completed'=>'Completed','cancelled'=>'Cancel'] as $v=>$l):?><button name="status" value="<?=$v?>" class="btn btn-sm btn-outline-dark mb-1" <?=$r['status']===$v?'disabled':''?>><?=$l?></button> <?php endforeach;?></form>
<?php foreach($asg[$r['id']]??[] as $x):?><div><small>Technician: <b><?=e($x['name'])?></b> (<?=e($x['status'])?>)</small></div><?php endforeach;?><?php if(user()['role']==='admin'&&!in_array($r['status'],['approved','assigned'],true)):?><small class="text-muted">Approve the request to assign a technician.</small><?php elseif(user()['role']==='admin'&&!$techs):?><small class="text-danger">No active technical users. Approve an application or create one under Users.</small><?php endif;?><?php if(user()['role']==='admin'&&$techs&&in_array($r['status'],['approved','assigned'],true)):?><?php $cand=tech_candidates($db,(int)$r['id']);$LB=['free'=>['Free now','success'],'working'=>['Working now','warning'],'busy'=>['Busy','warning'],'unavailable'=>['Unavailable','danger'],'unset'=>['Availability not set','secondary']];?><div class="mt-2"><b>Assign a technician</b> <small class="text-muted">(best match first: skills, availability, current workload)</small></div>
<?php foreach($cand as $i=>$t):?><form method="post" class="d-flex flex-wrap align-items-center gap-2 border rounded p-2 mt-1" <?=$t['state']!=='free'?'onsubmit="return confirm(\'This technician is not free right now. Assign anyway?\')"':''?>><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="action" value="assign"><input type="hidden" name="technician_id" value="<?=(int)$t['id']?>"><div class="me-auto"><b><?=e($t['name'])?></b><?=$i===0&&$t['state']!=='unavailable'?' <span class="badge bg-primary">Recommended</span>':''?><br><small><?=e($t['spec']?:'No specialization set')?> · <?=(int)$t['yrs']?> yrs · active jobs: <?=(int)$t['active']?></small></div><span class="badge bg-<?=$LB[$t['state']][1]?>"><?=$LB[$t['state']][0]?></span><?=$t['match']?'<span class="badge bg-info text-dark">Skills match</span>':'<span class="badge bg-light text-dark border">No skills match</span>'?><button class="btn btn-sm btn-dark">Assign</button></form><?php endforeach;?><?php endif;?></div><?php endforeach;?></div></div></div></section><?php require __DIR__.'/../../app/Views/footer.php';?>
